var inputDone bool

func formatEdited(value decimal.Decimal, picture string) string {
	// Determine scale from picture (digits after '.')
	scale := 0
	if idx := strings.Index(picture, "."); idx >= 0 {
		for _, c := range picture[idx+1:] {
			if c == '9' || c == 'Z' {
				scale++
			}
		}
	}
	// Truncate/round already done; ensure value is at correct scale
	// Use absolute? No, assume positive. Handle sign if needed.
	neg := value.IsNegative()
	if neg {
		value = value.Neg()
	}
	// Get integer and fractional parts
	value = value.Truncate(int32(scale))
	// For formatting, we need string with exactly scale decimals
	// Use StringFixed
	s := value.StringFixed(int32(scale))
	// s = "1234.56" or "1234" if scale 0
	var intPartStr, fracPartStr string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", scale)
		}
	} else {
		intPartStr = s
	}

	// Count integer slots in picture (9 or Z before '.')
	intSlots := 0
	decPos := strings.Index(picture, ".")
	var intPic string
	if decPos >= 0 {
		intPic = picture[:decPos]
	} else {
		intPic = picture
	}
	for _, c := range intPic {
		if c == '9' || c == 'Z' {
			intSlots++
		}
	}
	// High-order truncation: keep low-order digits that fit
	if len(intPartStr) > intSlots {
		intPartStr = intPartStr[len(intPartStr)-intSlots:]
	}
	// Left pad intPartStr with zeros to intSlots
	if len(intPartStr) < intSlots {
		intPartStr = strings.Repeat("0", intSlots-len(intPartStr)) + intPartStr
	}

	// Build result character by character
	// We need to map integer digits onto the integer picture positions
	// Picture integer part includes commas etc.
	// We'll fill from left to right, consuming digits where pic has 9/Z
	result := []rune(picture)
	digitIdx := 0
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == '9' || c == 'Z' {
			result[i] = rune(intPartStr[digitIdx])
			digitIdx++
		} else {
			// comma etc stays as in picture
			result[i] = rune(c)
		}
	}
	// fractional part: fill 9's
	if scale > 0 {
		fracPicStart := decPos + 1
		digitIdx = 0
		for i := fracPicStart; i < len(picture); i++ {
			c := picture[i]
			if c == '9' || c == 'Z' {
				if digitIdx < len(fracPartStr) {
					result[i] = rune(fracPartStr[digitIdx])
					digitIdx++
				} else {
					result[i] = '0'
				}
			} else {
				result[i] = rune(c)
			}
		}
	}

	// Now apply Z suppression for integer part
	// Find last Z position in intPic (rightmost Z)
	lastZ := -1
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' {
			lastZ = i
		}
	}
	if lastZ >= 0 {
		// Determine if integer part is all zeros up to and including last mandatory 9? Actually suppression goes until last non-zero digit
		// Algorithm: scan integer digits left to right; if all digits up to a point are zero, replace with spaces
		// But need to handle that '0' digit that is significant should stay.
		// Standard: leading zeros that correspond to Z are replaced with spaces, and commas in suppressed zone become spaces.
		// Find the index of last non-zero digit in the integer digits (in terms of result positions that are digit slots)
		// If integer value is zero, then all Z positions become spaces, the final 9 remains '0'
		suppress := true
		for i := 0; i <= lastZ; i++ {
			pc := intPic[i]
			if pc == '9' || pc == 'Z' {
				if result[i] != '0' {
					suppress = false
				}
				if suppress {
					result[i] = ' '
				} else {
					// once non-zero found, stop suppressing (but we already replaced earlier)
				}
			} else {
				// comma
				if suppress {
					// check if there is any non-zero digit to the right within integer part
					// If still suppressing, comma becomes space
					// But we need to look ahead: if all remaining integer digits up to end are zero, comma stays suppressed
					// Simpler: if suppress is true at this point, make it space; later when suppress becomes false, commas remain
					// However comma that is between suppressed and non-suppressed should be handled
					// We need to know if there is any non-zero digit at or to the right
					hasNonZeroAhead := false
					for k := i + 1; k < len(intPic); k++ {
						if (intPic[k] == '9' || intPic[k] == 'Z') && result[k] != '0' {
							hasNonZeroAhead = true
							break
						}
						// Also if digit is '0' but it's the mandatory 9 and value is zero? then zero is not suppressed? Hmm
					}
					// Also check current suppression state for future digits: if hasNonZeroAhead then this comma should be kept? Actually in COBOL, commas inside suppressed zone become spaces
					// So if we are still in suppression, comma is space regardless of ahead? No, if ahead has non-zero, the comma should appear at position just before the non-zero zone?
					// Standard: suppression replaces leading zeros and commas that are to the left of first significant digit with spaces.
					if hasNonZeroAhead {
						// we need to decide: if the comma is before the first significant digit, it should be space
						// Since suppress is true, the comma is before first significant digit, so space
						result[i] = ' '
					} else {
						// If no non-zero ahead, but there is a mandatory 9 with zero, should comma be space? Yes if integer zero
						// For zero value, all commas are spaces
						result[i] = ' '
					}
				}
			}
			if pc == '9' || pc == 'Z' {
				if result[i] != ' ' && result[i] != '0' {
					// first significant digit found; from now on no more suppression
					// But we need to stop suppressing for subsequent Z positions? Actually loop continues but suppress flag controls replacement
					// Once we encounter non-zero, set suppress false so future Z's not replaced
					suppress = false
				} else if result[i] == ' ' {
					// still suppressing
				} else { // result[i]=='0' and suppress still true
					// keep suppress true
				}
			}
		}
		// Special case: if the mandatory 9 is zero and all Z's are spaces, commas are spaces, we have "      0"
	}

	if neg {
		// COBOL would show sign; just prefix
		// Not needed for this program
	}

	return string(result)
}

func quantizeTruncate(v decimal.Decimal, scale int32) decimal.Decimal {
	return v.Truncate(scale)
}

func quantizeRound(v decimal.Decimal, scale int32) decimal.Decimal {
	return v.Round(scale)
}

func moveToWsTax(v decimal.Decimal) {
	// PIC 9(7)V99 -> 7 integer digits, 2 decimals
	v = quantizeTruncate(v, 2)
	// High-order truncation: keep low-order 9 digits (7+2)
	// Implement by taking integer representation
	// Scale 2 => value*100 should fit in 9 digits
	// Use string method
	sign := 1
	if v.IsNegative() {
		sign = -1
		v = v.Neg()
	}
	// Get as integer of hundredths
	shifted := v.Shift(2) // multiply 100
	// shifted should be integer
	intVal := shifted.IntPart() // int64
	// Keep low 9 digits
	mod := int64(1000000000) // 10^9
	intVal = intVal % mod
	if sign < 0 {
		intVal = -intVal
	}
	WsTax = decimal.New(intVal, -2)
}

func moveToWsNet(v decimal.Decimal) {
	v = quantizeTruncate(v, 2)
	sign := 1
	if v.IsNegative() {
		sign = -1
		v = v.Neg()
	}
	shifted := v.Shift(2)
	intVal := shifted.IntPart()
	mod := int64(1000000000)
	intVal = intVal % mod
	if sign < 0 {
		intVal = -intVal
	}
	WsNet = decimal.New(intVal, -2)
}

func moveToWsTotalTax(v decimal.Decimal) {
	v = quantizeTruncate(v, 2)
	sign := 1
	if v.IsNegative() {
		sign = -1
		v = v.Neg()
	}
	shifted := v.Shift(2)
	intVal := shifted.IntPart()
	mod := int64(100000000000) // 10^11 for 9+2=11 digits
	intVal = intVal % mod
	if sign < 0 {
		intVal = -intVal
	}
	WsTotalTax = decimal.New(intVal, -2)
}

func parseRecord(line string) TaxRec {
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	}
	if len(line) > 13 {
		line = line[:13]
	}
	trId := line[0:5]
	raw := line[5 : 5+8]
	raw = strings.TrimSpace(raw)
	var inc decimal.Decimal
	if raw == "" {
		inc = decimal.NewFromInt(0)
	} else {
		// digits only, implied 2 decimals
		// raw may contain spaces? already trimmed
		// parse as integer
		d := decimal.RequireFromString(raw)
		inc = decimal.New(d.IntPart(), -2)
	}
	return TaxRec{TrId: trId, TrIncome: inc}
}

func main() {
	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer taxFile.Close()
	taxReader = bufio.NewReader(taxFile)

	MAIN_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT TAX-FILE
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	// CLOSE TAX-FILE handled by defer
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	// DISPLAY "TAXPAYERS: " WS-COUNT " TOTAL TAX: " WS-TOTAL-ED
	// WS-COUNT is PIC 9(3) unedited numeric -> zero padded 3 digits
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func READ_PARA() {
	line, err := taxReader.ReadString('\n')
	if err != nil {
		// EOF
		if len(line) == 0 {
			inputDone = true
			WsEofFlag = "Y"
			return
		}
		// last line without newline
		line = strings.TrimRight(line, "\r\n")
		taxRec = parseRecord(line)
		// Next read will be EOF, but we have a record now
		// Need to handle that the next call will return EOF
		// So we don't set done yet; but we need to remember to set done on next call
		// Instead, check if we just read content and err==io.EOF -> keep record, set flag to trigger on next read?
		// COBOL LINE SEQUENTIAL: EOF after last record. So we consumed last record, next READ will hit EOF.
		// Store that we have pending EOF for next call
		// Implement by using a peek: set a flag that next read is EOF
		// Simpler: if we got a line with EOF, treat as valid record, and set up reader to return EOF next time by not marking done now
		// But bufio ReadString with EOF still returns line; next call will return EOF with empty line -> then we mark done
		// So we should not mark done now
		// To achieve that, we need to not consume EOF as done if line != ""
		// So we need to buffer EOF state
		// We'll use a package var to remember EOF pending
		eofPending = true
		pendingLine := ""
		_ = pendingLine
		return
	}
	line = strings.TrimRight(line, "\r\n")
	taxRec = parseRecord(line)
	if eofPending {
		// this was after a previous EOF-with-data, shouldn't happen
	}
}

var eofPending bool

func init() {
	// wrap READ_PARA to handle eofPending correctly
	origReadPara := READ_PARA
	READ_PARA = func() {
		if eofPending {
			// previous read was last line with EOF, now we signal EOF
			eofPending = false
			inputDone = true
			WsEofFlag = "Y"
			return
		}
		origReadPara()
		if eofPending {
			// we just read last record, don't mark done yet; will mark on next call
			// inputDone stays false
		}
	}
}

// allow reassignment
var READ_PARA func()

func PROCESS_PARA() {
	tenThousand := decimal.NewFromInt(10000)
	fortyThousand := decimal.NewFromInt(40000)
	rate10 := decimal.RequireFromString("0.10")
	rate20 := decimal.RequireFromString("0.20")
	rate30 := decimal.RequireFromString("0.30")
	thousand := decimal.NewFromInt(1000)
	sevenThousand := decimal.NewFromInt(7000)

	if taxRec.TrIncome.Cmp(decimal.New(1000000, -2)) <= 0 { // <=10000.00
		// COMPUTE WS-TAX ROUNDED = TR-INCOME * 0.10
		v := taxRec.TrIncome.Mul(rate10)
		v = quantizeRound(v, 2)
		moveToWsTax(v)
	} else {
		if taxRec.TrIncome.Cmp(decimal.New(4000000, -2)) <= 0 {
			v := taxRec.TrIncome.Sub(tenThousand).Mul(rate20).Add(thousand)
			v = quantizeRound(v, 2)
			moveToWsTax(v)
		} else {
			v := taxRec.TrIncome.Sub(fortyThousand).Mul(rate30).Add(sevenThousand)
			v = quantizeRound(v, 2)
			moveToWsTax(v)
		}
	}
	// COMPUTE WS-NET = TR-INCOME - WS-TAX (truncated)
	vNet := taxRec.TrIncome.Sub(WsTax)
	moveToWsNet(vNet)
	// ADD WS-TAX TO WS-TOTAL-TAX
	moveToWsTotalTax(WsTotalTax.Add(WsTax))
	WsCount++
	WsIncEd = formatEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	READ_PARA()
}

